// Lambda receives an event and returns a response
// The event shape depends on the trigger (API Gateway, S3, SQS, etc.)

// Example: HTTP API trigger via API Gateway
import { APIGatewayProxyHandlerV2 } from 'aws-lambda';

export const handler: APIGatewayProxyHandlerV2 = async (event) => {
  console.log('Event:', JSON.stringify(event, null, 2));

  const name = event.queryStringParameters?.name ?? 'World';

  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: `Hello, ${name}!` }),
  };
};

// Example: S3 trigger — runs when a file is uploaded
import { S3Handler } from 'aws-lambda';
export const processUpload: S3Handler = async (event) => {
  for (const record of event.Records) {
    const bucket = record.s3.bucket.name;
    const key = record.s3.object.key;
    console.log(`Processing: s3://${bucket}/${key}`);
    // resize image, extract metadata, trigger workflow...
  }
};

// Example: Scheduled trigger (like cron) — runs on a schedule
import { ScheduledHandler } from 'aws-lambda';
export const dailyReport: ScheduledHandler = async (event) => {
  // Runs daily at 8am UTC
  console.log('Generating daily report...');
};
